function check(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
function rejects(callable $fn,int $status):void{try{$fn();}catch(LifeError $e){check($e->status===$status,'Expected HTTP status');return;}throw new RuntimeException('Expected rejection');}
