check($a['email']==='a@example.com','Email normalization');check($a['id']!==$b['id']&&$a['id']!==1,'Private account IDs');check($a['timezone']==='Europe/London','Detected timezone retained');check($accounts->signInEmail('A@example.com',$pw)['id']===$a['id'],'Normalized returning login');
