rejects(fn()=>$accounts->signInEmail('a@example.com','wrong-password'),401);rejects(fn()=>$accounts->signInEmail('missing@example.com',$pw),401);rejects(fn()=>$accounts->signUpEmail('a@example.com',$pw),409);rejects(fn()=>$accounts->signUpEmail('not-an-email',$pw),422);rejects(fn()=>$accounts->signUpEmail('short@example.com','short'),422);rejects(fn()=>$accounts->signUpEmail('long@example.com',str_repeat('x',73)),422);rejects(fn()=>$accounts->signUpEmail('null@example.com',"twelvechars\0password"),422);check((int)$db->query('SELECT COUNT(*) FROM life_account')->fetchColumn()===3,'Rejected creation leaves no orphan account');
$sa=new LifeStore($db,(int)$a['id']);$sb=new LifeStore($db,(int)$b['id']);$r=$sa->read();$r=$sa->mutate($r['version'],'task.save',['title'=>'Private email A','listId'=>$r['state']['lists'][0]['id']]);$id=$r['state']['tasks'][0]['id'];check(count($sb->read()['state']['tasks'])===0&&count($owner->read()['state']['tasks'])===0,'Email tasks isolated from B and owner');rejects(fn()=>$sb->mutate($sb->read()['version'],'task.rename',['id'=>$id,'title'=>'Cross-account']),404);
$aiA=new LifeAI($sa);$aiB=new LifeAI($sb);$r=$aiA->read();$aiA->mutate($r['version'],'memory.save',['text'=>'Private email memory']);check(count($aiB->read()['state']['memories'])===0,'Email AI context isolated');
